<?php
require_once __DIR__ . '/../../config/response.php'; require_once __DIR__ . '/../../config/security.php'; require_once __DIR__ . '/../../services/OnePipeClient.php'; require_once __DIR__ . '/../../services/PrivateStorage.php';
header('Cache-Control: no-store'); if($_SERVER['REQUEST_METHOD']!=='POST') jsonResponse(['success'=>false,'error'=>'Method not allowed.'],405); $pdo=Database::getInstance(); $input=getJsonInput(); $session=validateSession($pdo,getBearerToken()?:($input['token']??''),15); if(!$session['valid']||!empty($session['is_2fa_pending'])) jsonResponse(['success'=>false,'error'=>'Please sign in to continue.'],401); $uid=(int)$session['user']['id']; $currency=strtoupper(trim((string)($input['currency']??'NGN'))); if($currency!=='NGN') jsonResponse(['success'=>false,'error'=>'OnePipe account provisioning is currently available for NGN only.'],422);
$u=$pdo->prepare('SELECT id,full_name,email,phone FROM users WHERE id=? AND status=\'active\''); $u->execute([$uid]); $user=$u->fetch(); if(!$user||!$user['phone']) jsonResponse(['success'=>false,'error'=>'A verified phone number is required before creating a receiving account.'],422);
$w=$pdo->prepare("SELECT w.id,w.uuid,c.code FROM wallets w JOIN currencies c ON c.code=w.currency_code WHERE w.user_id=? AND w.currency_code=? AND w.status<>'closed' LIMIT 1"); $w->execute([$uid,$currency]); $wallet=$w->fetch(); if(!$wallet){$pdo->prepare("INSERT INTO wallets(uuid,user_id,currency_code,wallet_type,status) VALUES(?,?,?,?,?)")->execute([generateUUID(),$uid,$currency,'personal','active']); $wallet=['id'=>(int)$pdo->lastInsertId(),'uuid'=>null,'code'=>$currency];}
$existing=$pdo->prepare("SELECT account_name,bank_name,account_number_display,status FROM wallet_receiving_accounts WHERE wallet_id=? AND provider='onepipe' AND currency_code=? LIMIT 1"); $existing->execute([$wallet['id'],$currency]); if($row=$existing->fetch()) jsonResponse(['success'=>true,'account'=>$row]);
$requestRef='FWL-'.strtoupper(bin2hex(random_bytes(16))); $parts=preg_split('/\s+/',trim($user['full_name']),2); $customer=['name'=>$user['full_name'],'first_name'=>$parts[0]??$user['full_name'],'last_name'=>$parts[1]??'','email'=>$user['email'],'phone'=>$user['phone']]; $pdo->prepare("INSERT INTO wallet_receiving_accounts(uuid,wallet_id,user_id,provider,currency_code,status) VALUES(?,?,?,?,?,'provisioning')")->execute([generateUUID(),$wallet['id'],$uid,'onepipe',$currency]); $id=(int)$pdo->lastInsertId();
try{$response=(new OnePipeClient($pdo,'live'))->openAccount($customer,$requestRef); $account=OnePipeClient::extractAccount($response); if($account['account_number']==='') throw new RuntimeException('OnePipe did not return an account number.'); $enc=PrivateStorage::encrypt($account['account_number'],'wallet-account'); $last4=substr($account['account_number'],-4); $display='••••'.$last4; $pdo->prepare("UPDATE wallet_receiving_accounts SET provider_account_ref=?,account_name=?,bank_name=?,bank_code=?,account_number_encrypted=?,account_number_last4=?,account_number_hash=?,account_number_display=?,status='active',provider_payload=? WHERE id=?")->execute([$account['account_ref']?:$account['account_number'],$account['account_name'],$account['bank_name'],$account['bank_code'],$enc,$last4,hash('sha256',$account['account_number']),$display,json_encode($response),$id]); jsonResponse(['success'=>true,'account'=>['account_name'=>$account['account_name'],'bank_name'=>$account['bank_name'],'account_number'=>$account['account_number'],'status'=>'active']]);}catch(Throwable $e){$pdo->prepare("UPDATE wallet_receiving_accounts SET status='failed' WHERE id=?")->execute([$id]); error_log('OnePipe wallet provisioning failed: '.get_class($e)); jsonResponse(['success'=>false,'error'=>'The receiving account could not be created right now.'],502);}
